import sys
from collections import defaultdict, deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    names = input_data[1:n+1]

    graph = defaultdict(set)
    char_set = set("abcdefghijklmnopqrstuvwxyz")

    for i in range(n - 1):
        s1 = names[i]
        s2 = names[i+1]

        min_len = min(len(s1), len(s2))
        found_diff = False
        for j in range(min_len):
            if s1[j] != s2[j]:
                u, v = s1[j], s2[j]
                graph[u].add(v)
                found_diff = True
                break

        if not found_diff and len(s1) > len(s2):
            print("Impossible")
            return

    in_degree = {c: 0 for c in char_set}
    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1

    queue = deque([c for c in char_set if in_degree[c] == 0])
    result = []

    while queue:
        u = queue.popleft()
        result.append(u)

        if u in graph:
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

    if len(result) != 26:
        print("Impossible")
    else:
        print("".join(result))

if __name__ == "__main__":
    solve()
